import{z as l,x as o,o as e,c as d,q as t,j as r,D as E,d as A,s,S as B,b as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Sanitizers","description":"","frontmatter":{"title":"Sanitizers","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sanitizers.md","filePath":"cs/sanitizers.md","lastUpdated":1791063341000}'),S={name:"cs/sanitizers.md"};function p(D,a,u,h,c,m){const i=o("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="sanitizers" tabindex="-1">Sanitizers <a class="header-anchor" href="#sanitizers" aria-label="Permalink to &quot;Sanitizers&quot;">​</a></h1><div class="epigraph"><p>ASan 在影子内存里记账，越界与 UAF 变成立即中止；UBSan 抓未定义；MSan 抓未初始化。它们是测试时的预言，不是生产默认的零开销证明。</p><footer>—— Serebryany et al., AddressSanitizer, USENIX ATC 2012；对照 LLVM sanitizer 文档</footer></div><p>上一课<a href="/cs/static-taint-analysis">污点</a>是编译期的流规则，静态回答「数据从哪来」。缺口是<strong>把空间错误变成确定崩溃</strong>，好让 fuzz 停下来。本课收 ASan/MSan/UBSan/TSan 的分工，不讲如何绕过 ASan。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无 sanitizer 时，堆溢出可能「看起来能跑」：越界写的字节恰好落在没人用的填充里，缺陷静默潜伏到生产才爆。ASan 的思路是把侥幸变成必然崩溃：每次堆分配周围涂红区，访问内存前查影子内存——按 1 字节影子记录 8 字节真实内存的辅助地址空间——落在红区即中止；延迟释放把刚 free 的块隔离一阵，再访问即判 UAF。TSan 对每次访问维护向量时钟，无同步关系的并发访问同一位置即报数据竞争；MSan 跟踪未初始化位，直到它影响分支或输出。缺口是把这些放进 CI；生产用不同工具（GWP-ASan 抽样点名）。</p><h3 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h3><p>完整 ASan 运行慢约一倍、内存开销也翻倍，不宜当默认生产配置。发现阶段与发布阶段分开：测试开全套抓 bug，生产靠缓解与抽样兜底。</p><p><span class="marginnote">Serebryany et al. 2012。本课禁止利用未开 sanitizer 的差异写 exploit。</span></p><p><span class="marginnote">数字实例：ASan 按 1 字节影子记录 8 字节真实内存，程序访问 8 GB 堆约需 1 GB 影子表，这解释了「内存开销翻倍」从哪来；红区通常再垫几十字节，越界写偏 1 字节也会踩中涂色区。</span></p><p><span class="marginnote">直觉类比：影子内存像仓库门口的平面图——每次搬东西前先对图看一眼「这个格子归谁」。图上标红的过道、标灰的已退租格，一碰就当场报警，而不是等账目年底对不上才发现货被人动过。</span></p><p><span class="marginnote">常见误区：初学者容易以为「程序没崩就说明越界写没事」。实际上越界字节常落在堆块间的填充里，把后面的变量悄悄改掉——ASan 的价值正是把这种静默损坏提前换成必现崩溃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四种工具按错误类别分工：ASan 管空间——越界与 UAF；MSan 管未初始化；UBSan 管未定义行为——有符号溢出、错位对齐、空引用解引用；TSan 管并发。硬规矩只有一条：fuzz 目标必须链 ASan，否则 fuzz 器对静默越界跑上亿个输入也不会停。对照硬件缓解：一边发现，一边上线硬化，CET/PAC 这类机制接住漏网的。下一课浏览器沙箱：即使有洞也难出进程。</p>',14)),(e(),r(B,null,{default:E(()=>[s(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FUZZ%5B%22fuzz%20%E8%BE%93%E5%85%A5%22%5D%20--%3E%20ASAN%5B%22ASan%20%E4%B8%AD%E6%AD%A2%22%5D%0A%20%20ASAN%20--%3E%20BUG%5B%22%E5%8F%AF%E5%9B%9E%E5%BD%92%E7%BC%BA%E9%99%B7%22%5D%0A%20%20PROD%5B%22%E7%94%9F%E4%BA%A7%22%5D%20--%3E%20MITIG%5B%22CET%2FPAC%2F%E6%B2%99%E7%AE%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[A("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"sanitizer 是测试时的预言：把「未定义」提前钉成确定的中止点，fuzz 于是从「等可观察故障」变成「等第一次违规」，信号密度完全不同。发现课把洞变成票。沙箱下一课把爆炸半径从「全用户」收到「渲染进程」。两者互补：sanitizer 压低进入生产的 bug 数量，缓解与沙箱限制漏网 bug 的后果；前者的失败模式是漏检，后者的失败模式是单个 bug 拿到全部权限。",-1)),(e(),r(B,null,{default:E(()=>[s(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E4%B8%80%E6%AC%A1%E5%8F%AF%E7%96%91%E5%86%85%E5%AD%98%E8%AE%BF%E9%97%AE%22%5D%20--%3E%20KIND%7B%22%E9%94%99%E8%AF%AF%E5%B1%9E%E4%BA%8E%E5%93%AA%E4%B8%80%E7%B1%BB%3F%22%7D%0A%20%20KIND%20--%20%22%E8%B6%8A%E7%95%8C%2F%E6%82%AC%E5%9E%82%E6%8C%87%E9%92%88%22%20--%3E%20ASAN%5B%22%E6%9F%A5%E5%BD%B1%E5%AD%90%E5%86%85%E5%AD%98%3A%20%E7%BA%A2%E5%8C%BA%E6%88%96%E9%9A%94%E7%A6%BB%E5%8C%BA%3F%22%5D%0A%20%20ASAN%20--%20%22%E8%B8%A9%E4%B8%AD%22%20--%3E%20ABORT%5B%22%E7%AB%8B%E5%8D%B3%E4%B8%AD%E6%AD%A2%E5%B9%B6%E5%87%BA%E6%8A%A5%E5%91%8A%22%5D%0A%20%20KIND%20--%20%22%E8%AF%BB%E6%9C%AA%E5%88%9D%E5%A7%8B%E5%8C%96%E6%95%B0%E6%8D%AE%22%20--%3E%20MSAN%5B%22MSan%3A%20%E6%B1%A1%E6%9F%93%E4%BD%8D%E4%BC%A0%E5%88%B0%E5%88%86%E6%94%AF%E6%88%96%E8%BE%93%E5%87%BA%3F%22%5D%0A%20%20MSAN%20--%20%22%E6%98%AF%22%20--%3E%20ABORT%0A%20%20KIND%20--%20%22%E6%9C%89%E7%AC%A6%E5%8F%B7%E6%BA%A2%E5%87%BA%2F%E9%94%99%E4%BD%8D%E5%AF%B9%E9%BD%90%22%20--%3E%20UBSAN%5B%22UBSan%3A%20%E6%8C%89%E8%A1%8C%E4%B8%BA%E7%82%B9%E6%8A%A5%22%5D%0A%20%20KIND%20--%20%22%E5%B9%B6%E5%8F%91%E8%AE%BF%E9%97%AE%E6%97%A0%E5%90%8C%E6%AD%A5%22%20--%3E%20TSAN%5B%22TSan%3A%20%E5%90%91%E9%87%8F%E6%97%B6%E9%92%9F%E6%AF%94%E5%AF%B9%22%5D%0A%20%20TSAN%20--%20%22%E6%9E%84%E6%88%90%E7%AB%9E%E4%BA%89%22%20--%3E%20ABORT%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>这张图回答的问题是：四种 sanitizer 各守哪类错误、各自用什么内部状态下判——影子内存、污染位、行为点、向量时钟，最后都汇到同一个「立即中止」出口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写关闭 ASan 的技巧——生产二进制里关检测属发布工程取舍；也不写绕过红区与影子内存的 exploit 手法。浏览器沙箱下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>污点是流；sanitizer 是空间/并发预言。</li><li>fuzz 应开 ASan；生产靠缓解与抽样。</li><li>立即中止优于静默损坏。</li><li>下一课浏览器沙箱。</li><li>出处：Serebryany et al., ATC 2012；LLVM Sanitizers。</li></ul>',5))])}const f=l(S,[["render",p]]);export{F as __pageData,f as default};
